// petzko-edge — Cloudflare Worker for the stats / data layer.
//
// Phase 0: proves the Worker ↔ D1 pipeline end-to-end with a health check, a
// read (GET /api/stats), and a write (POST /api/visit, a simple counter). Real
// stats / guest log / guestbook endpoints get layered on from here.

// `Env` is generated by `wrangler types` (worker-configuration.d.ts) from the
// bindings in wrangler.jsonc — never hand-write it, so it can't drift from config.
// Secrets are set with `wrangler secret put` (not in wrangler.jsonc), so they
// aren't in the generated Env — declare them here via interface merging to stay
// typed without hand-writing the bindings.
declare global {
  interface Env {
    IP_SALT?: string
    // Local-only bypass for the Access-gated /api/admin/* routes — set in
    // .dev.vars (gitignored) so `wrangler dev` can exercise the admin flow
    // without Cloudflare Access in front. NEVER set in production: it disables
    // authentication. (ACCESS_AUD / ACCESS_TEAM_DOMAIN come from wrangler.jsonc
    // `vars`, so they're in the generated Env already.)
    ADMIN_DEV_BYPASS?: string
    // Per-cluster ingest auth for /api/telemetry/ingest. JSON map of
    // {cluster_id: token} so adding a cluster is one map entry. Set out-of-band
    // via `wrangler secret put TELEMETRY_TOKENS`; mirrored as a k8s Secret in
    // each cluster's collector. Never in git.
    TELEMETRY_TOKENS?: string
  }
}

// ── TelemetryHub (Durable Object) ─────────────────────────────────────────────
// A dumb fan-out relay: the Worker validates + persists ingests (D1 is the source
// of truth), then forwards the assembled fleet here; this object broadcasts it to
// every connected WebSocket. Pure in-memory + WebSocket hibernation — no storage.
// One instance (idFromName("fleet")) coordinates all live viewers.
const HUB_MAX_SOCKETS = 200

export class TelemetryHub {
  private ctx: DurableObjectState
  private last: string | null = null

  constructor(ctx: DurableObjectState) {
    this.ctx = ctx
  }

  async fetch(req: Request): Promise<Response> {
    const url = new URL(req.url)

    // Browser opens the live stream.
    if (url.pathname === '/connect') {
      if (req.headers.get('Upgrade') !== 'websocket') {
        return new Response('expected websocket', { status: 426 })
      }
      if (this.ctx.getWebSockets().length >= HUB_MAX_SOCKETS) {
        return new Response('too many connections', { status: 503 })
      }
      const pair = new WebSocketPair()
      const [client, server] = [pair[0], pair[1]]
      this.ctx.acceptWebSocket(server) // hibernation API
      if (this.last) {
        try {
          server.send(this.last) // seed the new client with the current fleet
        } catch {
          /* ignore */
        }
      }
      return new Response(null, { status: 101, webSocket: client })
    }

    // Worker pushes a new fleet payload to broadcast.
    if (url.pathname === '/broadcast' && req.method === 'POST') {
      this.last = await req.text()
      for (const ws of this.ctx.getWebSockets()) {
        try {
          ws.send(this.last)
        } catch {
          /* drop a broken socket */
        }
      }
      return new Response('ok')
    }

    return new Response('not found', { status: 404 })
  }

  // Hibernation handlers — we don't expect client→server messages; just keep the
  // socket alive and clean up on close.
  async webSocketMessage(): Promise<void> {}
  async webSocketClose(ws: WebSocket): Promise<void> {
    try {
      ws.close()
    } catch {
      /* already closed */
    }
  }
  async webSocketError(): Promise<void> {}
}

export default {
  async fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(req.url)
    const pathname = url.pathname
    const method = req.method

    try {
      // Liveness — no DB touch.
      if (method === 'GET' && pathname === '/api/health') {
        return json({ ok: true })
      }

      // Read: current aggregate numbers to display on the site.
      if (method === 'GET' && pathname === '/api/stats') {
        const [visits, uniques] = await Promise.all([
          getCounter(env, 'visits'),
          getUniques(env),
        ])
        return json({ visits, uniques })
      }

      // Write: bump the page-view counter and record the (hashed) unique visitor.
      // The SPA beacons this on load.
      if (method === 'POST' && pathname === '/api/visit') {
        const [visits] = await Promise.all([
          bumpCounter(env, 'visits'),
          recordUnique(env, req),
        ])
        return json({ visits })
      }

      // Guest log — recent signed entries for the viewer.
      if (method === 'GET' && pathname === '/api/guestbook') {
        const entries = await listGuestbook(env, clampLimit(url.searchParams.get('limit')))
        return json({ entries })
      }

      // Guest log — sign a new entry (the hidden `:sign` command posts here).
      if (method === 'POST' && pathname === '/api/guestbook') {
        return signGuestbook(env, req)
      }

      // Public: site content — about, contacts, portfolio from D1 (60s CDN TTL).
      if (method === 'GET' && pathname === '/api/content') {
        const { results } = await env.DB.prepare(
          "SELECT key, value FROM content WHERE key IN ('about','contacts','portfolio')",
        ).all<{ key: string; value: string }>()
        const out: Record<string, unknown> = {}
        for (const row of results ?? []) {
          try {
            out[row.key] = JSON.parse(row.value)
          } catch {
            // skip malformed row
          }
        }
        return new Response(JSON.stringify(out), {
          status: 200,
          headers: {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'public, max-age=60',
          },
        })
      }

      // Public: live cluster telemetry — latest snapshot per cluster (fleet
      // shape), served cached. The poll fallback for clients without WebSocket.
      if (method === 'GET' && pathname === '/api/telemetry') {
        return new Response(await buildFleet(env), {
          status: 200,
          headers: {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'public, max-age=30',
          },
        })
      }

      // Public: live telemetry stream — WebSocket fan-out via the TelemetryHub
      // Durable Object. Updates are pushed the instant the collector ingests.
      if (method === 'GET' && pathname === '/api/telemetry/stream') {
        const stub = env.TELEMETRY_HUB.get(env.TELEMETRY_HUB.idFromName('fleet'))
        return stub.fetch('https://hub/connect', req)
      }

      // Ingest: a cluster's collector pushes its sanitized snapshot here. Machine
      // auth (per-cluster bearer token), NOT Cloudflare Access (non-interactive).
      if (method === 'POST' && pathname === '/api/telemetry/ingest') {
        return ingestTelemetry(env, req, ctx)
      }

      // ── Admin (Cloudflare Access–gated) ──
      // Access enforces auth at the edge for /api/admin/*; we independently
      // verify the signed Access JWT here (defense in depth) and read identity.
      if (method === 'GET' && pathname === '/api/admin/me') {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)
        return json({ email: id.email })
      }

      // Post-login bounce. Access gates this path, so reaching it with a valid
      // JWT means the user just authenticated — send them back into the app
      // with the admin section auto-opened (?admin=1).
      if (method === 'GET' && pathname === '/api/admin/login') {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)
        return Response.redirect(new URL('/?admin=1', req.url).toString(), 302)
      }

      // Admin: write site content (about / contacts / portfolio) to D1.
      if (method === 'PUT' && pathname === '/api/admin/content') {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)

        let body: { about?: unknown; contacts?: unknown; portfolio?: unknown }
        try {
          body = (await req.json()) as typeof body
        } catch {
          return json({ error: 'bad_request' }, 400)
        }

        const errs: string[] = []
        if (body.about !== undefined && !validateAbout(body.about)) errs.push('about')
        if (body.contacts !== undefined && !validateContacts(body.contacts)) errs.push('contacts')
        if (body.portfolio !== undefined && !validatePortfolio(body.portfolio)) errs.push('portfolio')
        if (errs.length) return json({ error: 'invalid', fields: errs }, 422)

        const now = Date.now()
        const entries: [string, unknown][] = []
        if (body.about !== undefined) entries.push(['about', body.about])
        if (body.contacts !== undefined) entries.push(['contacts', body.contacts])
        if (body.portfolio !== undefined) entries.push(['portfolio', body.portfolio])

        // Upsert all provided sections in a single batch so the write is atomic
        // — a partial failure can't leave content half-updated.
        if (entries.length) {
          const upsert = env.DB.prepare(
            `INSERT INTO content (key, value, updated_at) VALUES (?, ?, ?)
             ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
          )
          await env.DB.batch(
            entries.map(([key, value]) => upsert.bind(key, JSON.stringify(value), now)),
          )
        }

        return json({ ok: true })
      }

      // Admin: all guestbook rows (including unapproved) for moderation.
      if (method === 'GET' && pathname === '/api/admin/guestbook') {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)
        const { results } = await env.DB.prepare(
          `SELECT id, name, message, country, created_at, approved
             FROM guestbook
            ORDER BY created_at DESC
            LIMIT 200`,
        ).all()
        return json({ entries: results ?? [] })
      }

      // Admin: approve or hide a guestbook entry.
      const gbPatchMatch = pathname.match(/^\/api\/admin\/guestbook\/(\d+)$/)
      if (method === 'PATCH' && gbPatchMatch) {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)
        const entryId = Number(gbPatchMatch[1])

        let body: { approved?: unknown }
        try {
          body = (await req.json()) as typeof body
        } catch {
          return json({ error: 'bad_request' }, 400)
        }
        if (body.approved !== 0 && body.approved !== 1)
          return json({ error: 'invalid' }, 422)

        await env.DB.prepare('UPDATE guestbook SET approved = ? WHERE id = ?')
          .bind(body.approved, entryId)
          .run()
        return json({ ok: true })
      }

      // Admin: delete a guestbook entry.
      const gbDeleteMatch = pathname.match(/^\/api\/admin\/guestbook\/(\d+)$/)
      if (method === 'DELETE' && gbDeleteMatch) {
        const id = await verifyAccess(req, env)
        if (!id) return json({ error: 'unauthenticated' }, 401)
        const entryId = Number(gbDeleteMatch[1])

        await env.DB.prepare('DELETE FROM guestbook WHERE id = ?').bind(entryId).run()
        return json({ ok: true })
      }

      return json({ error: 'not_found' }, 404)
    } catch (err) {
      // Log the detail (visible in Workers Logs); return a generic message so
      // internals aren't leaked to clients.
      console.error(
        JSON.stringify({ level: 'error', path: pathname, message: String(err) }),
      )
      return json({ error: 'internal' }, 500)
    }
  },
} satisfies ExportedHandler<Env>

// ── D1 helpers (parameterized — never string-concat SQL) ──────────────────────

async function getCounter(env: Env, key: string): Promise<number> {
  const row = await env.DB.prepare('SELECT value FROM counters WHERE key = ?')
    .bind(key)
    .first<{ value: number }>()
  return row?.value ?? 0
}

async function bumpCounter(env: Env, key: string): Promise<number> {
  await env.DB.prepare(
    `INSERT INTO counters (key, value) VALUES (?, 1)
     ON CONFLICT(key) DO UPDATE SET value = value + 1`,
  )
    .bind(key)
    .run()
  return getCounter(env, key)
}

async function getUniques(env: Env): Promise<number> {
  const row = await env.DB.prepare(
    'SELECT COUNT(*) AS n FROM unique_visitors',
  ).first<{ n: number }>()
  return row?.n ?? 0
}

// Record a unique visitor by a salted hash of their IP — the raw IP is never
// stored. Cloudflare sets CF-Connecting-IP at the edge; falls back to a constant
// for local `wrangler dev` (no real edge), so the path is still exercised.
async function recordUnique(env: Env, req: Request): Promise<void> {
  const ipHash = await clientIpHash(env, req)
  await env.DB.prepare(
    'INSERT OR IGNORE INTO unique_visitors (ip_hash, first_seen) VALUES (?, ?)',
  )
    .bind(ipHash, Date.now())
    .run()
}

// Salted hash of the client IP — used for unique counting and guestbook
// rate-limiting. Raw IP is never persisted.
async function clientIpHash(env: Env, req: Request): Promise<string> {
  const ip = req.headers.get('CF-Connecting-IP') ?? 'local'
  if (!env.IP_SALT) {
    console.warn(
      JSON.stringify({ level: 'warn', message: 'IP_SALT not set — using dev fallback salt' }),
    )
  }
  return sha256Hex(`${env.IP_SALT ?? 'dev-insecure-salt'}:${ip}`)
}

// ── Guest log ─────────────────────────────────────────────────────────────────

const NAME_MAX = 40
const MESSAGE_MAX = 280
const RATE_LIMIT = 3 // entries…
const RATE_WINDOW_MS = 60 * 60 * 1000 // …per hour, per hashed IP

interface GuestEntry {
  id: number
  name: string
  message: string
  country: string | null
  created_at: number
}

function clampLimit(raw: string | null): number {
  const n = Math.floor(Number(raw))
  if (!Number.isFinite(n) || n <= 0) return 20
  return Math.min(n, 50)
}

async function listGuestbook(env: Env, limit: number): Promise<GuestEntry[]> {
  const { results } = await env.DB.prepare(
    `SELECT id, name, message, country, created_at
       FROM guestbook
      WHERE approved = 1
      ORDER BY created_at DESC
      LIMIT ?`,
  )
    .bind(limit)
    .all<GuestEntry>()
  return results ?? []
}

async function signGuestbook(env: Env, req: Request): Promise<Response> {
  let body: { name?: unknown; message?: unknown }
  try {
    body = (await req.json()) as typeof body
  } catch {
    return json({ error: 'bad_request' }, 400)
  }

  const name = typeof body.name === 'string' ? body.name.trim() : ''
  const message = typeof body.message === 'string' ? body.message.trim() : ''
  if (!name || name.length > NAME_MAX) return json({ error: 'invalid_name' }, 422)
  if (!message || message.length > MESSAGE_MAX) return json({ error: 'invalid_message' }, 422)
  if (isProfane(name) || isProfane(message)) return json({ error: 'rejected' }, 422)

  const ipHash = await clientIpHash(env, req)

  // Rate limit: at most RATE_LIMIT entries per window from one hashed IP.
  const since = Date.now() - RATE_WINDOW_MS
  const recent = await env.DB.prepare(
    'SELECT COUNT(*) AS n FROM guestbook WHERE ip_hash = ? AND created_at > ?',
  )
    .bind(ipHash, since)
    .first<{ n: number }>()
  if ((recent?.n ?? 0) >= RATE_LIMIT) return json({ error: 'rate_limited' }, 429)

  const rawCountry = req.cf?.country
  const country: string | null = typeof rawCountry === 'string' ? rawCountry : null
  const createdAt = Date.now()
  const res = await env.DB.prepare(
    `INSERT INTO guestbook (name, message, country, created_at, approved, ip_hash)
     VALUES (?, ?, ?, ?, 1, ?)`,
  )
    .bind(name, message, country, createdAt, ipHash)
    .run()

  const entry: GuestEntry = {
    id: Number(res.meta.last_row_id ?? 0),
    name,
    message,
    country,
    created_at: createdAt,
  }
  return json({ entry }, 201)
}

// Light profanity guard — a coarse safety net, not the primary control (the real
// control is rate-limiting + manual deletion). Substring match, case-insensitive.
const PROFANITY = ['fuck', 'shit', 'bitch', 'cunt', 'nigger', 'faggot', 'retard']
function isProfane(s: string): boolean {
  const lower = s.toLowerCase()
  return PROFANITY.some((w) => lower.includes(w))
}

// ── Live cluster telemetry ────────────────────────────────────────────────────
// Each cluster's in-cluster collector POSTs a curated, sanitized snapshot to
// /api/telemetry/ingest (machine auth, per-cluster token). We keep the latest
// snapshot per cluster in D1 (one row per cluster_id) and serve them together as
// a fleet — so adding a cluster needs no schema/API change. Reads compute a
// per-cluster `stale` flag, so a downed cluster shows offline while the rest
// stay live (and the site keeps working off the bundled/last-known data).

// A snapshot older than this is considered offline in the read response.
const TELEMETRY_STALE_MS = 150_000
// Reject ingests whose generated_at drifts further than this from now (replay /
// clock-skew guard).
const TELEMETRY_MAX_SKEW_MS = 120_000
// Hard cap on accepted ingest body size.
const TELEMETRY_MAX_BYTES = 16_384

// Assemble the current fleet payload (the {generated_at, clusters, fleet} shape)
// from D1. Shared by the poll endpoint, the WebSocket broadcast, and cold start.
async function buildFleet(env: Env): Promise<string> {
  const { results } = await env.DB.prepare(
    'SELECT cluster_id, role, value, updated_at FROM telemetry',
  ).all<{ cluster_id: string; role: string; value: string; updated_at: number }>()

  const now = Date.now()
  const clusters: Record<string, unknown>[] = []
  for (const row of results ?? []) {
    let snapshot: Record<string, unknown>
    try {
      snapshot = JSON.parse(row.value) as Record<string, unknown>
    } catch {
      continue // skip a malformed row rather than failing the whole read
    }
    clusters.push({
      cluster_id: row.cluster_id,
      role: row.role,
      stale: now - row.updated_at > TELEMETRY_STALE_MS,
      updated_at: row.updated_at,
      ...snapshot,
    })
  }

  // Fleet rollup — sum COUNTS only; never average utilization across clusters
  // of different sizes (it's meaningless). Utilization stays per-cluster.
  const online = clusters.filter((c) => !c.stale)
  const fleet = {
    clusters_total: clusters.length,
    clusters_online: online.length,
    nodes: sumField(clusters, ['cluster', 'nodes_total']),
    pods: sumField(clusters, ['workloads', 'pods_running']),
  }

  return JSON.stringify({ generated_at: now, clusters, fleet })
}

// Sum a nested numeric field across cluster snapshots (missing/non-number → 0).
function sumField(clusters: Record<string, unknown>[], path: [string, string]): number {
  let total = 0
  for (const c of clusters) {
    const group = c[path[0]] as Record<string, unknown> | undefined
    const v = group?.[path[1]]
    if (typeof v === 'number' && Number.isFinite(v)) total += v
  }
  return total
}

async function ingestTelemetry(
  env: Env,
  req: Request,
  ctx: ExecutionContext,
): Promise<Response> {
  // Body-size cap before parsing.
  const raw = await req.text()
  if (raw.length > TELEMETRY_MAX_BYTES) return json({ error: 'too_large' }, 413)

  let body: Record<string, unknown>
  try {
    body = JSON.parse(raw) as Record<string, unknown>
  } catch {
    return json({ error: 'bad_request' }, 400)
  }

  const clusterId = typeof body.cluster_id === 'string' ? body.cluster_id : ''
  if (!clusterId) return json({ error: 'bad_request' }, 400)

  // Per-cluster auth: the token presented must match the one registered for the
  // claimed cluster_id (so one cluster's token can't spoof another's metrics).
  let tokens: Record<string, string> = {}
  try {
    tokens = JSON.parse(env.TELEMETRY_TOKENS ?? '{}') as Record<string, string>
  } catch {
    console.error(JSON.stringify({ level: 'error', message: 'TELEMETRY_TOKENS not valid JSON' }))
  }
  const expected = tokens[clusterId]
  const presented = bearer(req)
  if (!expected || !presented || !timingSafeEqual(presented, expected)) {
    return json({ error: 'unauthenticated' }, 401)
  }

  // Replay / clock-skew guard.
  const generatedAt = typeof body.generated_at === 'number' ? body.generated_at : 0
  if (!generatedAt || Math.abs(Date.now() - generatedAt) > TELEMETRY_MAX_SKEW_MS) {
    return json({ error: 'stale_or_skewed' }, 422)
  }

  const snapshot = sanitizeSnapshot(body)
  if (!snapshot) return json({ error: 'invalid' }, 422)

  const role = body.role === 'primary' ? 'primary' : 'replica'
  await env.DB.prepare(
    `INSERT INTO telemetry (cluster_id, role, value, updated_at) VALUES (?, ?, ?, ?)
     ON CONFLICT(cluster_id) DO UPDATE SET role=excluded.role, value=excluded.value, updated_at=excluded.updated_at`,
  )
    .bind(clusterId, role, JSON.stringify(snapshot), Date.now())
    .run()

  // Fan out the updated fleet to live WebSocket clients via the hub (best-effort;
  // the poll endpoint + D1 are the source of truth, so don't fail ingest on it).
  ctx.waitUntil(
    (async () => {
      try {
        const fleet = await buildFleet(env)
        const stub = env.TELEMETRY_HUB.get(env.TELEMETRY_HUB.idFromName('fleet'))
        await stub.fetch('https://hub/broadcast', { method: 'POST', body: fleet })
      } catch (err) {
        console.error(JSON.stringify({ level: 'error', message: 'hub broadcast failed', detail: String(err) }))
      }
    })(),
  )

  return json({ ok: true })
}

// Read a Bearer token from the Authorization header.
function bearer(req: Request): string | null {
  const h = req.headers.get('Authorization') ?? ''
  const m = h.match(/^Bearer\s+(.+)$/i)
  return m ? m[1].trim() : null
}

// Constant-time string compare (avoids leaking token length/contents via timing).
function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return diff === 0
}

// Rebuild a clean snapshot from known fields only — drops anything unexpected,
// clamps numbers, caps array/string sizes. The collector already sanitizes
// in-cluster; this is defense in depth at the trust boundary.
interface TelemetrySnapshot {
  cluster: {
    k8s_version: string
    talos_version: string
    uptime_seconds: number
    nodes_ready: number
    nodes_total: number
    load_1?: number
    load_5?: number
    load_15?: number
  }
  resources: {
    cpu_used_cores: number
    cpu_total_cores: number
    mem_used_bytes: number
    mem_total_bytes: number
    storage_used_bytes?: number
    storage_total_bytes?: number
  }
  workloads: { pods_running: number; pods_total: number; namespaces: number }
  argocd?: { apps_synced: number; apps_total: number; apps_healthy: number }
  nodes: { name: string; cpu_pct: number; mem_pct: number; ready: boolean }[]
  services?: string[]
}

function sanitizeSnapshot(body: Record<string, unknown>): TelemetrySnapshot | null {
  const cluster = obj(body.cluster)
  const resources = obj(body.resources)
  const workloads = obj(body.workloads)
  if (!cluster || !resources || !workloads) return null

  const out: TelemetrySnapshot = {
    cluster: {
      k8s_version: str(cluster.k8s_version, 40),
      talos_version: str(cluster.talos_version, 40),
      uptime_seconds: num(cluster.uptime_seconds),
      nodes_ready: num(cluster.nodes_ready),
      nodes_total: num(cluster.nodes_total),
    },
    resources: {
      cpu_used_cores: num(resources.cpu_used_cores),
      cpu_total_cores: num(resources.cpu_total_cores),
      mem_used_bytes: num(resources.mem_used_bytes),
      mem_total_bytes: num(resources.mem_total_bytes),
    },
    workloads: {
      pods_running: num(workloads.pods_running),
      pods_total: num(workloads.pods_total),
      namespaces: num(workloads.namespaces),
    },
    nodes: Array.isArray(body.nodes)
      ? body.nodes.slice(0, 16).map((n) => {
          const node = obj(n) ?? {}
          return {
            name: str(node.name, 40),
            cpu_pct: clampPct(node.cpu_pct),
            mem_pct: clampPct(node.mem_pct),
            ready: Boolean(node.ready),
          }
        })
      : [],
  }

  // Load average is optional (node-exporter); preserve fractional values.
  if (typeof cluster.load_1 === 'number') {
    out.cluster.load_1 = num(cluster.load_1)
    out.cluster.load_5 = num(cluster.load_5)
    out.cluster.load_15 = num(cluster.load_15)
  }

  // Storage is optional (depends on Longhorn metrics being scraped).
  if (typeof resources.storage_total_bytes === 'number') {
    out.resources.storage_used_bytes = num(resources.storage_used_bytes)
    out.resources.storage_total_bytes = num(resources.storage_total_bytes)
  }

  // ArgoCD is optional (depends on its ServiceMonitor being enabled).
  const argocd = obj(body.argocd)
  if (argocd) {
    out.argocd = {
      apps_synced: num(argocd.apps_synced),
      apps_total: num(argocd.apps_total),
      apps_healthy: num(argocd.apps_healthy),
    }
  }

  // Services manifest is optional (depends on ArgoCD metrics). Cap count + length.
  if (Array.isArray(body.services)) {
    out.services = body.services
      .filter((s): s is string => typeof s === 'string')
      .slice(0, 100)
      .map((s) => s.slice(0, 60))
  }

  return out
}

function obj(v: unknown): Record<string, unknown> | null {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null
}
function str(v: unknown, max: number): string {
  return typeof v === 'string' ? v.slice(0, max) : ''
}
function num(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : 0
}
function clampPct(v: unknown): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) return 0
  return Math.max(0, Math.min(100, Math.round(v)))
}

// ── Cloudflare Access (Zero Trust) JWT verification ───────────────────────────
// Access sits in front of /api/admin/* and only lets authenticated requests
// through, attaching a signed JWT (Cf-Access-Jwt-Assertion header + the
// CF_Authorization cookie). We re-verify that JWT here — RS256 signature against
// the team's rotating public keys, audience (this app's AUD tag), and expiry —
// so the Worker never trusts the edge blindly. Returns the caller's identity, or
// null when unauthenticated.

interface AccessIdentity {
  email: string
  sub: string
}

// Cache the team's JWKS (public keys); they rotate, so re-fetch hourly.
let accessKeys: { keys: Map<string, CryptoKey>; fetchedAt: number } | null = null
const JWKS_TTL_MS = 60 * 60 * 1000

async function accessJwks(env: Env): Promise<Map<string, CryptoKey>> {
  if (accessKeys && Date.now() - accessKeys.fetchedAt < JWKS_TTL_MS) {
    return accessKeys.keys
  }
  // `wrangler types` narrows committed vars to string-literal types (e.g. "" while
  // unset), which collapse to `never` after a truthiness guard — widen to string.
  const team = env.ACCESS_TEAM_DOMAIN as string
  if (!team) throw new Error('ACCESS_TEAM_DOMAIN not configured')
  const res = await fetch(`${team.replace(/\/$/, '')}/cdn-cgi/access/certs`)
  if (!res.ok) throw new Error(`Access JWKS fetch failed: ${res.status}`)
  const { keys: jwks } = (await res.json()) as { keys: (JsonWebKey & { kid: string })[] }
  const keys = new Map<string, CryptoKey>()
  for (const jwk of jwks) {
    const key = await crypto.subtle.importKey(
      'jwk',
      jwk,
      { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
      false,
      ['verify'],
    )
    keys.set(jwk.kid, key)
  }
  accessKeys = { keys, fetchedAt: Date.now() }
  return keys
}

async function verifyAccess(req: Request, env: Env): Promise<AccessIdentity | null> {
  const token =
    req.headers.get('Cf-Access-Jwt-Assertion') ?? readCookie(req, 'CF_Authorization')

  // No token: in local `wrangler dev` there's no Access in front, so an explicit
  // (gitignored, dev-only) bypass lets the flow be exercised. Never set in prod.
  if (!token) {
    if (env.ADMIN_DEV_BYPASS === '1') return { email: 'dev@localhost', sub: 'dev' }
    return null
  }

  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [rawHeader, rawPayload, rawSig] = parts

  let header: { alg?: string; kid?: string }
  let payload: { aud?: string | string[]; email?: string; sub?: string; exp?: number }
  try {
    header = JSON.parse(b64urlDecode(rawHeader))
    payload = JSON.parse(b64urlDecode(rawPayload))
  } catch {
    return null
  }
  if (header.alg !== 'RS256' || !header.kid) return null

  const key = (await accessJwks(env)).get(header.kid)
  if (!key) return null

  const ok = await crypto.subtle.verify(
    'RSASSA-PKCS1-v1_5',
    key,
    b64urlBytes(rawSig),
    new TextEncoder().encode(`${rawHeader}.${rawPayload}`),
  )
  if (!ok) return null

  // Audience must include this app's AUD tag, and the token must not be expired.
  const aud = env.ACCESS_AUD as string
  const auds = Array.isArray(payload.aud) ? payload.aud : payload.aud ? [payload.aud] : []
  if (!aud || !auds.includes(aud)) return null
  const now = Math.floor(Date.now() / 1000)
  if (typeof payload.exp === 'number' && payload.exp <= now) return null

  return { email: payload.email ?? 'unknown', sub: payload.sub ?? '' }
}

function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get('Cookie')
  if (!raw) return null
  for (const part of raw.split(';')) {
    const eq = part.indexOf('=')
    if (eq === -1) continue
    if (part.slice(0, eq).trim() === name) return part.slice(eq + 1).trim()
  }
  return null
}

// base64url → bytes / UTF-8 string (JWT segments are base64url, no padding).
function b64urlBytes(s: string): Uint8Array {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/')
  const pad = b64.length % 4 === 0 ? '' : '='.repeat(4 - (b64.length % 4))
  const bin = atob(b64 + pad)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

function b64urlDecode(s: string): string {
  return new TextDecoder().decode(b64urlBytes(s))
}

async function sha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input))
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
}

// ── Admin content validators ──────────────────────────────────────────────────
// Mirror the shapes in frontend/src/admin/model.ts; deliberately simple —
// validate presence + types + length caps so the DB never gets junk.

function isStr(v: unknown, maxLen = 100_000): boolean {
  return typeof v === 'string' && v.length <= maxLen
}

function validateAbout(x: unknown): boolean {
  if (!x || typeof x !== 'object') return false
  const o = x as Record<string, unknown>
  return (
    isStr(o.heading, 200) &&
    isStr(o.avatar, 500) &&
    isStr(o.avatarAlt, 200) &&
    isStr(o.body, 20_000)
  )
}

function validateContacts(x: unknown): boolean {
  if (!Array.isArray(x) || x.length > 50) return false
  return x.every(
    (c) =>
      c &&
      typeof c === 'object' &&
      isStr((c as Record<string, unknown>).type, 50) &&
      isStr((c as Record<string, unknown>).url, 500) &&
      isStr((c as Record<string, unknown>).description, 1000),
  )
}

function validatePortfolio(x: unknown): boolean {
  if (!Array.isArray(x) || x.length > 50) return false
  return x.every(
    (p) =>
      p &&
      typeof p === 'object' &&
      isStr((p as Record<string, unknown>).type, 50) &&
      isStr((p as Record<string, unknown>).name, 200) &&
      isStr((p as Record<string, unknown>).url, 500) &&
      isStr((p as Record<string, unknown>).company, 200) &&
      isStr((p as Record<string, unknown>).description, 5_000),
  )
}

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      // Same-origin in prod (route on petzko.sh), so CORS isn't required.
      'cache-control': 'no-store',
    },
  })
}
